{
  "post": {
    "tags": [
      "portal"
    ],
    "summary": "Book a rate by rate_id",
    "description": "Book a rate you got from `GET /v1/portal/rates` with its `rate_id` and your own `team_reference` (your CRM id for the shipment). One booking per `rate_id`.\n\n- **201**: booked. `price` is the booking price.\n- **200**: the same `rate_id` and `team_reference` again (a retry) returns the booking you already have.\n- **404** `unknown rate_id`: the id does not exist or was issued to another team.\n- **409**: the `rate_id` is already booked under another `team_reference`.\n- **410**: the rate expired (see `valid_until`); fetch a fresh rate and book that.\n- **503**: the booking system is unavailable; the message says how to book by email with the airline instead.\n\nA mail \"Booking <booking_reference> confirmed\" from the airline reaches your mailbox shortly after: the shipment is then booked and ready to ship. There is no status call; keep the booking in your own CRM. Bookings are not counted against the rate-read limit. A booking can be cancelled with `DELETE /v1/portal/bookings/{booking_reference}`.",
    "operationId": "create_booking_v1_portal_bookings_post",
    "requestBody": {
      "content": {
        "application/json": {
          "schema": {
            "$ref": "#/components/schemas/BookingIn"
          }
        }
      },
      "required": true
    },
    "responses": {
      "201": {
        "description": "Successful Response",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/BookingOut"
            }
          }
        }
      },
      "200": {
        "description": "Retry: the booking you already have.",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/BookingOut"
            }
          }
        }
      },
      "404": {
        "description": "unknown rate_id"
      },
      "409": {
        "description": "rate_id already booked under another team_reference"
      },
      "410": {
        "description": "rate expired, fetch a fresh rate"
      },
      "503": {
        "description": "booking system unavailable, book by email with the airline"
      },
      "422": {
        "description": "Validation Error",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/HTTPValidationError"
            }
          }
        }
      }
    },
    "security": [
      {
        "Team key": []
      }
    ]
  }
}
/v1/portal/bookings/{booking_reference} ['delete']
{
  "delete": {
    "tags": [
      "portal"
    ],
    "summary": "Cancel a booking",
    "description": "Cancel one of your bookings by its `booking_reference`, whether it was made here or by email with the airline, before or after its confirmation mail. A cancelled booking no longer counts as a booking for its shipment, and its `rate_id` cannot be booked again (fetch a fresh rate to book again).\n\n- **200**: cancelled. Calling it again returns the same answer.\n- **404** `unknown booking_reference`: no such booking, or it belongs to another team.\n\nCancellations are not counted against the rate-read limit.",
    "operationId": "cancel_booking_v1_portal_bookings__booking_reference__delete",
    "security": [
      {
        "Team key": []
      }
    ],
    "parameters": [
      {
        "name": "booking_reference",
        "in": "path",
        "required": true,
        "schema": {
          "type": "string",
          "pattern": "^BK-[A-Z0-9]{8}$",
          "title": "Booking Reference"
        }
      }
    ],
    "responses": {
      "200": {
        "description": "Successful Response",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/CancelOut"
            }
          }
        }
      },
      "404": {
        "description": "unknown booking_reference"
      },
      "422": {
        "description": "Validation Error",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/HTTPValidationError"
            }
          }
        }
      }
    }
  }
}

